cnt = 0
for s in open('9.csv'):
    M = [int(x) for x in s.split(';')]
    copied = [x for x in M if M.count(x) == 3]
    nor_copied = [x for x in M if M.count(x) == 1]
    if len(copied) == 3 and len(nor_copied) == 3:
        if sum(copied)  2 > sum(nor_copied)  2:
            cnt += 1
print(cnt)

